// mathUtils.js
export const PI = 3.14159;
export function poleKola(promien) { return PI * promien ** 2; }

// inny-plik.js
async function ladujModul() {
  const modul = await import("./mathUtils.js");
  console.log(modul.poleKola(3)); // ok. 28.27
}
ladujModul();

// stringUtils.js
export function slugify(str) { return str.toLowerCase().trim().replace(/\s+/g, "-"); }

// inny-plik.js
async function ladujModul() {
  const modul = await import("./stringUtils.js");
  console.log(modul.slugify("Dynamiczny Import Modulu")); // "dynamiczny-import-modulu"
}
ladujModul();

// mathUtils.js
export function dodaj(a, b) { return a + b; }

// inny-plik.js
function ladujMate() {
  import("./mathUtils.js").then((modul) => {
    console.log(modul.dodaj(5, 5)); // 10
  });
}
ladujMate();

async function zle() {
  const modul = import("./mathUtils.js"); // BRAK await!
  console.log(modul); // Promise { <pending> } - NIE obiekt modulu!
  console.log(modul.dodaj); // undefined - Promise nie ma pola 'dodaj'
}

// import() ZAWSZE zwraca Promise, niezaleznie od kontekstu. Bez await
// (lub .then()) zmienna modul przechowuje SAM obiekt Promise, a nie
// faktyczny, "rozwiazany" obiekt modulu z jego eksportami - probu dostepu
// do modul.dodaj daje undefined, bo Promise nie posiada takiego pola.

// stringUtils.js
export function capitalize(str) { return str.charAt(0).toUpperCase() + str.slice(1); }

// inny-plik.js
async function obslugujKlikniecie() {
  const modul = await import("./stringUtils.js");
  console.log(modul.capitalize("lazy loading")); // "Lazy loading"
}

// Takie podejscie poprawia wydajnosc, poniewaz modul stringUtils.js jest
// pobierany DOPIERO w momencie faktycznego wywolania obslugujKlikniecie(),
// a nie od razu przy starcie calej aplikacji - jesli funkcja ta jest
// rzadko uzywana (np. tylko po kliknieciu konkretnego przycisku), reszta
// uzytkownikow nie musi "placic" czasem ladowania za kod, ktorego nigdy
// nie uzyja.

// mathUtils.js
export function procent(wartosc, proc) { return (wartosc * proc) / 100; }

// inny-plik.js
async function ladujProcent() {
  const modul = await import("./mathUtils.js");
  console.log(modul.procent(500, 20)); // 100
}
ladujProcent();

// Import statyczny (import { x } from './plik.js' na gorze pliku):
// - musi znajdowac sie NA GORZE pliku, przed jakimkolwiek innym kodem
// - ladowany NATYCHMIAST, zanim jakikolwiek kod zacznie sie wykonywac
// - uzywany dla PODSTAWOWEJ logiki, potrzebnej ZAWSZE, od razu przy starcie
//
// Import dynamiczny (import('./plik.js'), z nawiasami, jak wywolanie funkcji):
// - moze byc uzyty w DOWOLNYM miejscu kodu (nie tylko na gorze pliku)
// - zwraca Promise, ladowanie odbywa sie ASYNCHRONICZNIE, 'na zadanie'
// - uzywany dla duzych, rzadko potrzebnych modulow (np. po kliknieciu
//   przycisku) - poprawia wydajnosc poczatkowego ladowania aplikacji
//   (technika 'lazy loading'/'code-splitting', wykorzystywana przez
//   React.lazy() w projektach React)

// Kolory.js
export const paleta = ["czerwony", "zielony"];

// main.js
async function main() {
  const { paleta } = await import("./Kolory.js");
  console.log(paleta[0]); // -> "czerwony"
}
main();

// Waga.js
export default function przelicz(kg) {
  return kg * 2.20462;
}

// main.js
import("./Waga.js").then((modul) => {
  console.log(Math.round(modul.default(10))); // -> 22
});

// A.js
export const wartosc = 10;

// B.js
export const wartosc = 20;

// main.js
Promise.all([import("./A.js"), import("./B.js")]).then(([a, b]) => {
  console.log(a.wartosc + b.wartosc); // -> 30
});

// main.js
async function main() {
  try {
    await import("./brak.js");
  } catch (e) {
    console.log(e.constructor.name); // -> "Error" (modul nie istnieje)
  }
}
main();

// Licznik.js
let n = 0;
n++;
export default n;

// main.js
async function main() {
  const a = await import("./Licznik.js");
  const b = await import("./Licznik.js");
  console.log(a.default, b.default, a === b); // -> 1 1 true
}
main();

// ModulA.js
export default "wersja A";

// ModulB.js
export default "wersja B";

// main.js
async function warunkowaImportacja(flaga) {
  const modul = flaga ? await import("./ModulA.js") : await import("./ModulB.js");
  return modul.default;
}
warunkowaImportacja(true).then(console.log);  // -> "wersja A"
warunkowaImportacja(false).then(console.log); // -> "wersja B"

// Panel.js
export default function Panel() {
  return "Panel administratora";
}

// main.js
async function ladujKomponent() {
  const modul = await import("./Panel.js");
  return modul.default();
}
ladujKomponent().then(console.log); // -> "Panel administratora"

// Nazywane jest to "lazy loading" (leniwym ladowaniem), poniewaz kod modulu
// Panel.js nie jest pobierany ani wykonywany, dopoki funkcja ladujKomponent
// nie zostanie faktycznie wywolana - jesli ta funkcja jest rzadko uzywana,
// wiekszosc uzytkownikow nigdy nie "placi" kosztem jej zaladowania.

// Temperatura.js
export default function celsjuszNaFahrenheit(c) {
  return (c * 9) / 5 + 32;
}

// main.js
async function main() {
  const modul = await import("./Temperatura.js");
  console.log(modul.default(0)); // -> 32
}
main();

// Statystyka.js
export function srednia(t) {
  return t.reduce((s, x) => s + x, 0) / t.length;
}

// main.js
async function main() {
  const { srednia } = await import("./Statystyka.js");
  console.log(srednia([2, 4, 6])); // -> 4
}
main();

// Rejestr.js
export default class Rejestr {
  wpisy = [];
  dodaj(wpis) {
    this.wpisy.push(wpis);
  }
}

// main.js
async function main() {
  const { default: Rejestr } = await import("./Rejestr.js");
  const r = new Rejestr();
  r.dodaj("a");
  r.dodaj("b");
  console.log(r.wpisy.length); // -> 2
}
main();

// FormaterWaluty.js
export default (n) => n.toFixed(2) + " zl";

// FormaterProcentu.js
