// main.js
async function zaladujFormatera(typ) {
  const modul = typ === "waluta" ? await import("./FormaterWaluty.js") : await import("./FormaterProcentu.js");
  return modul.default;
}
zaladujFormatera("waluta").then((f) => console.log(f(12.5)));
zaladujFormatera("procent").then((f) => console.log(f(0.25)));

// Walidator.js
export function jestEmailem(s) {
  return s.includes("@");
}

// main.js
import("./Walidator.js").then(({ jestEmailem }) => {
  console.log(jestEmailem("test@test.com"), jestEmailem("zly"));
