// StanAplikacji.js
export default { gotowe: false };

// main.js
async function ustaw() {
  const modul = await import("./StanAplikacji.js");
  modul.default.gotowe = true;
}
async function sprawdz() {
  const modul = await import("./StanAplikacji.js");
  return modul.default.gotowe;
}
async function main() {
  await ustaw();
  console.log(await sprawdz()); // -> true
}
main();

// Raport.js
export default function generujRaport() {
  return "raport gotowy";
}

// main.js
async function ladujRaport(dostepny) {
  if (!dostepny) return "brak danych";
  const modul = await import("./Raport.js");
  return modul.default();
}
ladujRaport(false).then(console.log); // -> "brak danych"
ladujRaport(true).then(console.log);  // -> "raport gotowy"

