// main.js
// Wersja sekwencyjna - czeka na A.js, POTEM zaczyna ladowac B.js:
async function sekwencyjnie() {
  const a = await import("./A.js");
  const b = await import("./B.js");
  return a.wartosc + b.wartosc;
}

// Wersja rownolegla - oba moduly zaczynaja sie ladowac JEDNOCZESNIE:
async function rownolegle() {
  const [a, b] = await Promise.all([import("./A.js"), import("./B.js")]);
  return a.wartosc + b.wartosc;
}

